export const meta = {
  name: 'archy-research-loop',
  description: 'Loop-until-dry web research for tools/techniques archy could adopt, each candidate adversarially vetted',
  phases: [
    { title: 'Find', detail: 'three search angles per round, fed what earlier rounds already saw' },
    { title: 'Verify', detail: 'two independent refuters per fresh candidate: gates/dup, and facts/feasibility' },
  ],
}

const CONTEXT = `
You are researching for archy (repo at /Users/hosanglee/archy, GitHub hslee16/archy): a Python CLI + MCP server for
static architecture analysis of Python codebases (import graph, layer rules, cycles, DSM, composite score, impact,
co-change coupling, hotspots, duplicates, conventions, snapshot/diff loop for agents, import-linter contracts).
Before searching, read enough of these to know what archy already does and what has already FAILED:
- README.md, docs/SHIPPED.md, docs/FUTURE.md, docs/ROADMAP.md
- docs/WHAT_DIDNT_WORK.md (critical: every pre-registered claim came back null; six "push a fact at the agent"
  delivery interventions were all null, two cost more. Measured: 0 structural regressions in 25 live agent runs (#356);
  humans break declared contracts on 0.66% of commits (#359).)
- docs/research/CODEGRAPH_COMPETITIVE_ANALYSIS.md, docs/research/AXIS_REVIEW.md (OECD four-condition gate for any score axis)
- \`uv run archy --help\`
Project gates every proposal must pass:
1. Anti-theater: what does an agent or human DO differently because of this? A different action, not a nicer number.
2. Any signal reaching the score must pass the OECD gate (independence, directionality, actionability, discriminant validity).
3. Usage priority: archy has <20 real users. Proposals that lower adoption friction, fix correctness, or create a usage
   signal outrank new capability. A seventh "deliver facts to the agent" idea needs a reason it differs from the six nulls.
4. Already-rejected: per-session structural attribution ledgers, \`archy install --hooks\` (#132 parked).
For GitHub use \`gh api\` REST only (never GraphQL, never \`gh issue view\`). Use WebSearch/WebFetch (load via ToolSearch) for the internet.
`

const CAND = {
  type: 'object',
  properties: {
    candidates: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          key: { type: 'string', description: 'short kebab-case slug identifying the idea' },
          title: { type: 'string' },
          source_tools: { type: 'string', description: 'the external tools/papers this comes from, with URLs' },
          what: { type: 'string', description: 'concretely what archy would add or change' },
          action_changed: { type: 'string', description: 'who does what differently because of it (anti-theater answer)' },
          evidence: { type: 'string', description: 'evidence it matters: adoption, measurements, user demand. Say if weak.' },
          size: { type: 'string', enum: ['good-first-issue', 'small', 'medium', 'large'] },
          archy_files: { type: 'string', description: 'where in archy it would land' },
        },
        required: ['key', 'title', 'source_tools', 'what', 'action_changed', 'evidence', 'size', 'archy_files'],
      },
    },
  },
  required: ['candidates'],
}

const VERDICT = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean' },
    reason: { type: 'string' },
    duplicate_of: { type: 'string', description: 'existing archy issue/PR number if it duplicates one, else empty' },
    corrected_scope: { type: 'string', description: 'if it survives, the tightened scope a ticket should carry' },
  },
  required: ['refuted', 'reason', 'duplicate_of', 'corrected_scope'],
}

const ANGLES = [
  { key: 'py-arch-tools', prompt: 'Survey Python architecture/dependency tools and what they do that archy lacks or does worse: tach (gauge-sh), import-linter/grimp, deptry, pydeps, pyan, pyreverse, emerge, vulture, pylint design checks, Ruff rules relevant to imports, Pants/Bazel dependency inference, and anything newer you find (2025-2026). Look at their issue trackers for highly-upvoted requests, adoption numbers, and integrations (pre-commit, CI, SARIF, editor). Also look for small polish features (output formats, config ergonomics, error messages) that would be good first issues.' },
  { key: 'agent-code-intel', prompt: 'Survey code-intelligence tools built for AI coding agents (2025-2026): MCP servers for code graphs (e.g. Serena, codegraph/code-graph-rag, Sourcegraph/Amp, Aider repo-map, Claude Code/Codex/Cursor plugins, Greptile, Augment context engine, etc.). Focus on what is MEASURED to help agents and how they get adopted (distribution, zero-config, install UX). Be skeptical of vendor claims; note which have independent evidence. Remember archy measured delivery-to-agent ideas as null six times, so look specifically for things that differ in kind.' },
  { key: 'other-ecosystems-research', prompt: 'Survey architecture-conformance tools in other ecosystems and academic techniques: ArchUnit (Java), dependency-cruiser and madge (JS), Nx module boundaries, Go arch-go, cargo-modules, NDepend, Structure101, Lattix, Sonargraph, CodeScene, Arcan/Designite architectural-smell detection, decoupling level / propagation cost metrics, co-change coupling research, architecture erosion studies (2022-2026). Extract features or techniques that would transfer to a Python tool and have evidence behind them (adoption or empirical studies), plus small transferable ergonomics (rule syntax, baseline/ratchet files, freeze/allowlist of existing violations, SARIF, reporting) that may be good first issues.' },
]

const seen = new Map()   // key -> candidate
const seenTitles = []
const confirmed = []
const rejected = []
let dry = 0
let round = 0
const MAX_ROUNDS = 4
const MAX_FRESH = 10

while (dry < 1 && round < MAX_ROUNDS) {
  round++
  log(`Round ${round}: ${seen.size} ideas seen so far, ${confirmed.length} confirmed`)
  const already = seenTitles.length
    ? `\nIdeas ALREADY found in earlier rounds (do not resubmit these or near-variants; find NEW ones, dig deeper or into sources not yet covered):\n- ${seenTitles.join('\n- ')}\n`
    : ''
  const found = (await parallel(ANGLES.map(a => () =>
    agent(`${CONTEXT}\nResearch angle (round ${round}): ${a.prompt}\n${already}\nReturn up to 6 candidate proposals for archy, each grounded in a real source with URL. Include good-first-issue-sized items where they genuinely exist. Prefer fewer, well-evidenced candidates over many speculative ones. Pre-filter yourself against the gates; drop anything that fails them.`,
      { phase: 'Find', label: `find:${a.key}:r${round}`, schema: CAND })
  ))).filter(Boolean).flatMap(r => r.candidates)

  const norm = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-')
  let fresh = found.filter(c => !seen.has(norm(c.key)))
  const uniq = new Map()
  fresh.forEach(c => { if (!uniq.has(norm(c.key))) uniq.set(norm(c.key), c) })
  fresh = [...uniq.values()]
  if (fresh.length > MAX_FRESH) log(`Round ${round}: ${fresh.length} fresh, verifying first ${MAX_FRESH}; dropped: ${fresh.slice(MAX_FRESH).map(c => c.key).join(', ')}`)
  fresh = fresh.slice(0, MAX_FRESH)
  fresh.forEach(c => { seen.set(norm(c.key), c); seenTitles.push(c.title) })
  if (!fresh.length) { dry++; log(`Round ${round}: nothing new`); continue }

  const judged = await parallel(fresh.map(c => () => {
    const desc = JSON.stringify(c, null, 2)
    return parallel([
      () => agent(`${CONTEXT}\nYou are a skeptic. Try to REFUTE this proposal on the project's gates. Check: does it fail anti-theater? Does it repeat something in docs/WHAT_DIDNT_WORK.md or docs/research/*? Does archy ALREADY do it (grep src/archy, run the CLI)? Is it a duplicate of an existing issue? Search ALL issues including closed: \`gh api 'search/issues?q=repo:hslee16/archy+<terms>&per_page=30' --jq '.items[]|"\\(.number) [\\(.state)] \\(.title)"'\` with several term variants. Is it below the usage-priority line with no adoption argument? Default to refuted=true if uncertain.\n\nProposal:\n${desc}`,
        { phase: 'Verify', label: `gate:${c.key}`, schema: VERDICT }),
      () => agent(`${CONTEXT}\nYou are a skeptic. Try to REFUTE this proposal on FACTS and FEASIBILITY. Open the cited sources (WebFetch) and confirm the external tool really does what is claimed and the evidence is real (adoption, measurement), not vendor marketing. Check in archy's code whether it is feasible at the claimed size; for 'good-first-issue' size confirm a newcomer could do it in one small PR with clear acceptance criteria. Default to refuted=true if uncertain.\n\nProposal:\n${desc}`,
        { phase: 'Verify', label: `facts:${c.key}`, schema: VERDICT }),
    ]).then(vs => ({ c, votes: vs.filter(Boolean) }))
  }))
  for (const j of judged) {
    const ok = j.votes.length === 2 && j.votes.every(v => !v.refuted)
    ;(ok ? confirmed : rejected).push(j)
  }
  log(`Round ${round}: ${judged.filter(j => j.votes.length === 2 && j.votes.every(v => !v.refuted)).length}/${judged.length} survived`)
}

return {
  rounds: round,
  confirmed: confirmed.map(j => ({ ...j.c, verdicts: j.votes })),
  rejected: rejected.map(j => ({ key: j.c.key, title: j.c.title, size: j.c.size, reasons: j.votes.map(v => ({ refuted: v.refuted, reason: v.reason, dup: v.duplicate_of })) })),
}

